def transform(grid):
    # The uniform separator is color 4/6. The region after it is a mask:
    # retain foreground pixels from the region before it only where the
    # corresponding mask cell is nonzero.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            upper = grid[:r]
            lower = grid[r + 1:]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                for x, y in zip(upper, lower)
            ]
    for c in range(len(grid[0])):
        if len({row[c] for row in grid}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)]
                for x, y in zip(left, right)
            ]
